import{_ as r,D as t,c as l,j as i,a as e,I as a,a4 as s,o as h}from"./chunks/framework.CRCV4hx_.js";const q=JSON.parse('{"title":"Cart Booking Component","description":"","frontmatter":{},"headers":[],"relativePath":"cart-booking.md","filePath":"cart-booking.md"}'),d={name:"cart-booking.md"},c={id:"cart-booking-component",tabindex:"-1"},p=i("a",{class:"header-anchor",href:"#cart-booking-component","aria-label":'Permalink to "Cart Booking Component <Badge type="tip" text="NEW" />"'},"​",-1),k=s(`<p>The <code>AvailabilityMultiResults</code> Livewire component is a cart-based booking surface for a <strong>single Entry</strong>. Instead of booking one date range and one rate at a time, the visitor can pick <strong>quantities per rate</strong>, add those selections to a running booking, change the dates and add more, and finally check out everything as a <strong>single reservation</strong>.</p><p>This is ideal for excursions, tours, classes, or any product where a customer books several units (or several dates) in one go. For the simpler one-rate / one-date flow, use the <a href="./availability-results">Availability Results</a> component instead.</p><h2 id="component-basics" tabindex="-1">Component basics <a class="header-anchor" href="#component-basics" aria-label="Permalink to &quot;Component basics&quot;">​</a></h2><p>Pair the component with an <a href="./availability-search-component">Availability Search</a> instance so the visitor can pick dates and quantities. In its most basic form:</p><div class="language-antlers vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">antlers</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">livewire:availability-search</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :rates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :any-rate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">livewire:availability-multi-results</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :entry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>Because the component is rate-driven, the <code>availability-search</code> it is paired with should run with <code>:rates=&quot;true&quot;</code> and <code>:any-rate=&quot;true&quot;</code> so that every rate is returned for the searched dates.</p><p>A common pattern is to loop a collection and render a multi-results block per entry:</p><div class="language-antlers vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">antlers</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">collection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">excursions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">livewire:availability-search</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :entry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;id&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :rates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :any-rate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">livewire:availability-multi-results</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :entry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">collection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">excursions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><p>Both the <code>&lt;livewire:...&gt;</code> and the Antlers <code>{{ livewire:... }}</code> syntaxes work.</p><h2 id="component-properties" tabindex="-1">Component properties <a class="header-anchor" href="#component-properties" aria-label="Permalink to &quot;Component properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>entry</td><td>string</td><td>none - required</td><td><strong>Needs to be a Statamic Entry ID.</strong> The Entry the cart books against. Passed as the <code>mount</code> parameter.</td></tr><tr><td>rates</td><td>boolean</td><td>true</td><td>Defaults to <code>true</code> here: the component is rate-driven and always resolves per-rate labels and prices.</td></tr><tr><td>showExtras</td><td>boolean or string</td><td>false</td><td>Show the Extras component inside the cart panel. Set to <code>true</code> for all extras, or a filter slug. (more information below)</td></tr><tr><td>showOptions</td><td>boolean or string</td><td>false</td><td>Show the Options component inside the cart panel. Set to <code>true</code> for all options, or a filter slug. (more information below)</td></tr><tr><td>overrideRates</td><td>array</td><td>[]</td><td>Override the <code>rate_id =&gt; label</code> map instead of resolving labels from the Rate model.</td></tr><tr><td>view</td><td>string</td><td>&quot;availability-multi-results&quot;</td><td>You can override the view that is used to render the component. Expects a <code>name.blade.php</code> file in the <code>/resources/views/vendor/statamic-resrv/livewire</code> folder.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">NO <code>showRates</code> PROP</p><p>Unlike the <a href="./availability-search-multiple#the-availability-collection-component">Availability Collection</a> component, <code>availability-multi-results</code> does <strong>not</strong> have a <code>showRates</code> property. It always renders every available rate with its own quantity picker.</p></div><h2 id="the-cart-flow" tabindex="-1">The cart flow <a class="header-anchor" href="#the-cart-flow" aria-label="Permalink to &quot;The cart flow&quot;">​</a></h2><p>The component renders three areas that work together:</p><ol><li><strong>Per-rate quantity pickers.</strong> Once the visitor searches, each available rate is shown with its label, the per-unit price, an optional <a href="./rates#cancellation-policy">cancellation policy</a> label, and <code>-</code> / <code>+</code> buttons to set a quantity. Availability is always queried at quantity 1 so the displayed prices are per unit; the customer picks the quantity afterwards.</li><li><strong>Add to booking.</strong> When at least one rate has a quantity greater than zero, an <strong>&quot;Add to booking&quot;</strong> button appears. Clicking it pushes every selected rate (with its dates, rate, quantity, and price) into the cart and resets the pickers.</li><li><strong>Your booking.</strong> Once the cart has any selections, a <strong>&quot;Your booking&quot;</strong> panel lists every line item (rate label, quantity, date range, and line total) with a remove button, a running <strong>Total</strong>, a <strong>Clear</strong> link, and a <strong>&quot;Book now&quot;</strong> button.</li></ol><p>Because the dates come from the paired <code>availability-search</code>, the visitor can <strong>change the dates and add more selections</strong> to the same cart. Each &quot;Add to booking&quot; appends to the existing cart rather than replacing it, so a single booking can span several different date ranges and rates.</p><p>Clicking <strong>Book now</strong> validates the whole cart, creates the reservation, and redirects the visitor to the <a href="./checkout">Checkout</a> page.</p>`,17),u=s('<h2 id="extras-and-options-optional" tabindex="-1">Extras and Options (Optional) <a class="header-anchor" href="#extras-and-options-optional" aria-label="Permalink to &quot;Extras and Options (Optional)&quot;">​</a></h2><p>Like the <a href="./availability-results">Availability Results</a> component, you can display the Entry&#39;s Extras and Options inline. Here they render inside the &quot;Your booking&quot; cart panel and their pricing is recalculated against every selection in the cart:</p><div class="language-antlers vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">antlers</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">livewire:availability-multi-results</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :entry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;id&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :show-extras</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :show-options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>The selected extras and options are carried over to the <a href="./checkout">Checkout</a> component as usual.</p><h2 id="how-the-reservation-is-structured" tabindex="-1">How the reservation is structured <a class="header-anchor" href="#how-the-reservation-is-structured" aria-label="Permalink to &quot;How the reservation is structured&quot;">​</a></h2><p>When the visitor checks out, the cart is converted into a reservation that the normal checkout flow understands without any special handling:</p><ul><li><strong>One parent reservation</strong> is created. It stores the overall total price and the overall date span.</li><li><strong>One child reservation per cart selection</strong> is created, each with its own dates, rate, quantity, and price.</li></ul><p>The event-driven reservation lifecycle handles the rest: availability is decreased per child when the reservation is created, and increased again per child if it expires or is cancelled. The <a href="./checkout">Checkout</a> component treats the parent reservation exactly like a normal single reservation, so the whole cart is paid for in one transaction.</p><div class="info custom-block"><p class="custom-block-title">DATABASE MIGRATION</p><p>This feature adds a <code>price</code> column to the <code>resrv_child_reservations</code> table. The migration runs automatically with the package migrations; existing child reservation rows get <code>price = null</code>.</p></div><h2 id="how-the-cart-is-scoped-to-one-entry" tabindex="-1">How the cart is scoped to one entry <a class="header-anchor" href="#how-the-cart-is-scoped-to-one-entry" aria-label="Permalink to &quot;How the cart is scoped to one entry&quot;">​</a></h2><p>The cart lives in the session and is scoped to the Entry that owns it. Three session keys are used:</p><ul><li><code>resrv-search</code>: the shared search state (dates, quantity, rate).</li><li><code>resrv-multi-selections</code>: the cart itself.</li><li><code>resrv-multi-cart-entry</code>: which Entry owns the cart.</li></ul><p>When you visit a different Entry&#39;s multi-results page, the component detects that the persisted cart belongs to another Entry (or to none) and starts clean, so a cart never leaks between Entries. After checkout the cart and its owner are cleared, while any selected extras and options are left in the session for the Checkout component to copy onto the reservation.</p><h2 id="customizing" tabindex="-1">Customizing <a class="header-anchor" href="#customizing" aria-label="Permalink to &quot;Customizing&quot;">​</a></h2><p>The main template file can be found at <code>/resources/views/vendor/statamic-resrv/livewire/availability-multi-results.blade.php</code>. Publish the views first if you haven&#39;t already (either <a href="./installation">during installation</a> or by running <code>php artisan vendor:publish --tag=resrv-checkout-views</code>), then edit the file to choose which elements to display and how to style them.</p><h2 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h2><p>The component uses these frontend translation keys, which you can override as described in the <a href="./languages">Languages</a> page:</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th></tr></thead><tbody><tr><td><code>addToBooking</code></td><td>Add to booking</td></tr><tr><td><code>yourBooking</code></td><td>Your booking</td></tr><tr><td><code>total</code></td><td>Total</td></tr><tr><td><code>clear</code></td><td>Clear</td></tr><tr><td><code>bookNow</code></td><td>Book now</td></tr><tr><td><code>pleaseSelectRateToBook</code></td><td>Please select a rate to book</td></tr><tr><td><code>pleaseSelectDates</code></td><td>Please select dates to search for availability.</td></tr><tr><td><code>noAvailability</code></td><td>No availability</td></tr><tr><td><code>searchError</code></td><td>Search error</td></tr><tr><td><code>youAreTooLate</code></td><td>You are too late!</td></tr></tbody></table><p>The optional cancellation policy label also uses the cancellation keys (<code>nonRefundable</code>, <code>freeCancellationUntilDate</code>) documented on the <a href="./rates#cancellation-policy">Rates</a> page.</p>',19);function g(y,E,b,v,m,f){const o=t("Badge"),n=t("Image");return h(),l("div",null,[i("h1",c,[e("Cart Booking Component "),a(o,{type:"tip",text:"NEW"}),e(),p]),k,a(n,{src:"./img/resrv-availability-multi-results.webp",alt:"An AvailabilityMultiResults component showing per-rate quantity pickers and a running booking cart."}),u])}const F=r(d,[["render",g]]);export{q as __pageData,F as default};
